async function callAgent(prompt, opts, recovery, needed) {
  const role = opts.label
  for (let attempt = 1; attempt <= ATTEMPTS; attempt++) {
    if (runStop) throw stopRun()
    const retry = attempt > 1
    let result = null
    let why = 'no result (null: the agent died, was blocked, or was skipped)'
    try {
      result = await agent(retry ? retryHead(role, attempt, recovery) + prompt : prompt,
                           retry ? Object.assign({}, opts, { label: role + ':attempt' + attempt }) : opts)
    } catch (e) {
      const msg = String((e && e.message) || e).slice(0, 300)
      if (LIMIT_ERROR.test(msg)) throw stopRun(role + ', attempt ' + attempt + ' of ' + ATTEMPTS + ', failed on a usage or rate limit (' + msg + '), and is not run again now')
--- sw
out="$state/$(date -u +%Y%m%dT%H%M%SZ)-$mode.json"
cd "$repo"
case $mode in
  new)
    id=$(python3 -c 'import uuid; print(uuid.uuid4())')
    echo "$id" > "$state/session"
    { cat explorations/coordinator/skill-writer-brief.md
      printf '\n# Your first task\n\n'
      cat "$task"; } |
      claude -p --model opus --session-id "$id" --permission-mode acceptEdits \
        --allowedTools "${tools[@]}" --output-format json > "$out" ;;
  resume)
    id=$(cat "$state/session")
    claude -p --model opus --resume "$id" --permission-mode acceptEdits \
      --allowedTools "${tools[@]}" --output-format json < "$task" > "$out" ;;
  *) echo "usage: $0 new|resume <task-file>" >&2; exit 2 ;;
esac
--- ws
if [ -f "$state/session" ] && [ -f "$state/last" ] && [ -f "$state/written" ]; then
  if [ $(( now - $(cat "$state/last") )) -lt 3000 ] && [ "$(cat "$state/written")" -lt "$LIMIT" ]; then fresh=0; fi
fi
out="$state/$(date -u +%Y%m%dT%H%M%SZ).json"
if [ $fresh = 1 ]; then
  id=$(python3 -c 'import uuid; print(uuid.uuid4())'); echo "$id" > "$state/session"; echo 0 > "$state/written"
  { cat explorations/coordinator/skill-writer-brief.md
    printf '\n# This session\n\nYou are a stream writer: the coordinating session sends you tasks one after another, each a chunk of record entries or a part of a skill to write or fix. Your standing 
    claude -p --model opus --session-id "$id" --permission-mode acceptEdits \
      --allowedTools "${tools[@]}" --output-format json > "$out"
else
  id=$(cat "$state/session")
  printf '# Your next task\n\n%s\n' "$task" |
    claude -p --model opus --resume "$id" --permission-mode acceptEdits \
      --allowedTools "${tools[@]}" --output-format json > "$out"
fi
date +%s > "$state/last"
--- rl head
  ],
}

