cd /root/.claude/projects/-home-user-fortress && python3 - <<'E'
import json,re,glob
pat=re.compile(r'uppercase|upper-case|upper case|capital letter|capitals|lowercase|lower-case|lower case',re.I)
num=re.compile(r'radix|numeral|hex|digit',re.I)
for f in sorted(glob.glob('*.jsonl')):
    for l in open(f,errors='ignore'):
        if not pat.search(l): continue
        try: d=json.loads(l)
        except: continue
        t=d.get('type'); m=d.get('message',{})
        if t not in('user','assistant'): continue
        c=m.get('content')
        texts=[]
        if isinstance(c,str): texts=[c]
        elif isinstance(c,list):
            for b in c:
                if isinstance(b,dict) and b.get('type')=='text': texts.append(b.get('text',''))
        for x in texts:
            if x.startswith('This session is being continued'): continue
            for mm in pat.finditer(x):
                s=x[max(0,mm.start()-220):mm.end()+220].replace('\n',' ')
                if num.search(s): print(d.get('timestamp','?')[:16],t,'|',s,'\n')
