S=/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad && cat > $S/hugemethods.py <<'E'
import struct, sys, os
def scan(path):
    d=open(path,'rb').read()
    if d[:4]!=b'\xca\xfe\xba\xbe': return []
    p=8; n=struct.unpack('>H',d[p:p+2])[0]; p+=2
    cp=[None]*n; i=1
    while i<n:
        t=d[p]
        if t==1:
            l=struct.unpack('>H',d[p+1:p+3])[0]; cp[i]=d[p+3:p+3+l].decode('utf8','replace'); p+=3+l
        elif t in(3,4,9,10,11,12,17,18): p+=5
        elif t in(5,6): p+=9; i+=1
        elif t in(7,8,16,19,20): p+=3
        elif t==15: p+=4
        else: raise Exception('tag %d'%t)
        i+=1
    p+=6
    ni=struct.unpack('>H',d[p:p+2])[0]; p+=2+2*ni
    def attrs(p,cb=None):
        na=struct.unpack('>H',d[p:p+2])[0]; p+=2
        for _ in range(na):
            name,l=struct.unpack('>HI',d[p:p+6]); p+=6
            if cb: cb(cp[name],p)
            p+=l
        return p
    nf=struct.unpack('>H',d[p:p+2])[0]; p+=2
    for _ in range(nf): p=attrs(p+6)
    nm=struct.unpack('>H',d[p:p+2])[0]; p+=2
    out=[]
    for _ in range(nm):
        name=cp[struct.unpack('>H',d[p+2:p+4])[0]]
        def cb(an,q,name=name):
            if an=='Code': out.append((struct.unpack('>I',d[q+4:q+8])[0],name))
        p=attrs(p+6,cb)
    return out
res=[]
for root in sys.argv[1:]:
    for dp,_,fs in os.walk(root):
        for f in fs:
            if f.endswith('.class'):
                try:
                    for l,m in scan(os.path.join(dp,f)):
                        if l>8000: res.append((l,os.path.join(dp,f)[len(root)+1:],m))
                except Exception as e: print('ERR',f,e)
res.sort(reverse=True)
print(len(res),'methods over 8000 bytes')
import collections
by=collections.Counter(r[1].split('/')[3] if r[1].startswith('com/sun/fortress/') else r[1].split('/')[0] for r in res)
print(dict(by))
for l,c,m in res:
    if '/parser/' in c or '/syntax_abstractions/' in c: continue
    print(l,c,m)
E
python3 $S/hugemethods.py ProjectFortress/build | cut -c1-170 | head -50

